// 🧩 Insertar Fondo (Flux) — substitutes the real Flux background URL into
// the {{BACKGROUND_URL}} token that "🧩 Prep Render" deliberately left
// unresolved. Reads render_elements/index/width/height back from "🧩 Prep
// Render" via $('...').item.json because the upstream HTTP Request node
// (⚡ Flux Background) replaces $json with FAL's own response body — the
// same recovery pattern used by n8n/subworkflow-rehost-images.json's
// "🔧 Build blob URL" node.
const prep = $('🧩 Prep Render').item.json;
const imageUrl = $json.images && $json.images[0] && $json.images[0].url;
if (!imageUrl) {
  throw new Error('⚡ Flux Background: response missing images[0].url — ' + JSON.stringify($json).slice(0, 300));
}
const safeUrl = String(imageUrl).replace(/"/g, '\\"');
const jsonStr = JSON.stringify(prep.render_elements).replace(/\{\{\s*BACKGROUND_URL\s*\}\}/g, safeUrl);
const elements = JSON.parse(jsonStr);

return {
  json: {
    index: prep.index,
    width: prep.width,
    height: prep.height,
    elements,
  },
};

// 🧩 Insertar Fondo (Skip) — the closing-slide / no-background path. Runs
// directly off the IF node's FALSE branch, so $json here IS still "🧩 Prep
// Render"'s own output (no HTTP call in between to strip it). Substitutes
// {{BACKGROUND_URL}} with an empty string — harmless because templates
// that take this path (e.g. carousel-closing) never actually reference
// BACKGROUND_URL in their elements. This is the Flux-skip / Creatomate-only
// behavior — it still renders a real image, never an early "no image" marker.
const prep = $json;
const jsonStr = JSON.stringify(prep.render_elements).replace(/\{\{\s*BACKGROUND_URL\s*\}\}/g, "");
const elements = JSON.parse(jsonStr);

return {
  json: {
    index: prep.index,
    width: prep.width,
    height: prep.height,
    elements,
  },
};

// ⏱️ Check Status — tracks poll_count across loop iterations and enforces
// the ~120s poll budget (40 tries * 3s wait). Fails loud (throw) on a
// Creatomate "failed" status or on budget exhaustion — never silently
// returns a broken/placeholder image.
//
// On the FIRST pass (right after 🖌️ Creatomate Create), $json is the create
// response ({id, status}, no poll_count field yet) — poll_count starts at 0.
// On SUBSEQUENT passes (after 🔧 Fusionar Resultado Poll), poll_count is
// carried forward explicitly since the intervening HTTP GET node replaces
// $json with its own response body.
const prev = $json;
const prevPollCount = typeof prev.poll_count === "number" ? prev.poll_count : -1;
const pollCount = prevPollCount + 1;

if (prev.status === "failed") {
  throw new Error("Creatomate render " + (prev.id || "unknown") + " failed");
}
if (pollCount > 40) {
  throw new Error("Creatomate render " + (prev.id || "unknown") + " did not succeed within the ~120s poll budget (40 tries)");
}

return {
  json: {
    id: prev.id,
    status: prev.status,
    url: prev.url || null,
    poll_count: pollCount,
  },
};

// ✅ Return — emits the sub-workflow's per-item output contract
// { index, imageUrl }. Reads index from "🧩 Prep Render" (the poll chain
// never carries the original index through the Creatomate/FAL HTTP calls).
const prep = $('🧩 Prep Render').item.json;

return {
  json: {
    index: prep.index,
    imageUrl: $json.url,
  },
};

// 🔧 Fusionar Resultado Poll — the HTTP GET poll node replaces $json with
// its own response body ({id, status, url,...}), dropping poll_count. This
// node recovers poll_count from "⏱️ Check Status"'s most recent output in
// this same loop iteration (same recovery pattern as the rehost sub-
// workflow's "🔧 Build blob URL" node) before looping back to Check Status.
const prevCheck = $('⏱️ Check Status').item.json;

return {
  json: {
    id: $json.id || prevCheck.id,
    status: $json.status,
    url: $json.url || null,
    poll_count: prevCheck.poll_count,
  },
};

// 🗂️ Collect Results — "🔁 Loop Over Items"'s done-branch accumulates every
// looped-back { index, imageUrl } item across all iterations, but not
// necessarily in original order. Re-sort by index before returning so
// callers get results in the same order the input items arrived.
const items = $input.all();
const sorted = items
  .map((it) => it.json)
  .filter((r) => r && r.index !== undefined && r.index !== null)
  .sort((a, b) => a.index - b.index);

return sorted.map((r) => ({ json: r }));
